1	import assert from 'node:assert/strict';
2	import fs from 'node:fs';
3	import os from 'node:os';
4	import path from 'node:path';
5	import { execFileSync } from 'node:child_process';
6	import test from 'node:test';
7	import { Workspace } from '../src/workspace.js';
8	
9	const CLI = path.resolve('src/cli.js');
10	
11	function tempDir() {
12	  return fs.mkdtempSync(path.join(os.tmpdir(), 'lattice-migrate-'));
13	}
14	
15	function writeSnapshot(file, workspace) {
16	  fs.writeFileSync(file, `${JSON.stringify(workspace.exportJSON())}\n`);
17	}
18	
19	function workspaceWith(documents) {
20	  const workspace = new Workspace();
21	  for (const document of documents) workspace.add(document);
22	  return workspace;
23	}
24	
25	function runMigrate(args, cwd) {
26	  try {
27	    const stdout = execFileSync(process.execPath, [CLI, 'migrate', ...args], { cwd, encoding: 'utf8' });
28	    return { status: 0, stdout, stderr: '' };
29	  } catch (error) {
30	    return { status: error.status ?? 1, stdout: error.stdout?.toString() ?? '', stderr: error.stderr?.toString() ?? '' };
31	  }
32	}
33	
34	test('migrate merge builds from base, imports incoming, writes and prints one snapshot line', () => {
35	  const cwd = tempDir();
36	  writeSnapshot(path.join(cwd, 'base.json'), workspaceWith([
37	    { id: 'a', title: 'A', body: 'links [[b]]', tags: ['base'] },
38	  ]));
39	  writeSnapshot(path.join(cwd, 'incoming.json'), workspaceWith([
40	    { id: 'b', title: 'B', body: 'new doc [[ghost]]', tags: ['Incoming'] },
41	  ]));
42	  const output = path.join(cwd, 'out.json');
43	
44	  const { status, stdout, stderr } = runMigrate(['base.json', 'incoming.json', 'out.json', 'merge'], cwd);
45	  assert.equal(status, 0);
46	  assert.equal(stderr, '');
47	  const lines = stdout.split('\n');
48	  assert.equal(lines.length, 2);
49	  assert.equal(lines[1], '');
50	
51	  const printed = JSON.parse(lines[0]);
52	  const written = JSON.parse(fs.readFileSync(output, 'utf8'));
53	  assert.deepEqual(printed, written);
54	  assert.deepEqual(printed.documents.map((document) => document.id), ['a', 'b']);
55	  assert.equal(printed.documents[0].body, 'links [[b]]');
56	  assert.equal(printed.version, 1);
57	  assert.equal(typeof printed.checksum, 'string');
58	
59	  const expected = workspaceWith([
60	    { id: 'a', title: 'A', body: 'links [[b]]', tags: ['base'] },
61	    { id: 'b', title: 'B', body: 'new doc [[ghost]]', tags: ['incoming'] },
62	  ]).exportJSON();
63	  assert.deepEqual(printed, expected);
64	});
65	
66	test('migrate replace swaps the full document set', () => {
67	  const cwd = tempDir();
68	  writeSnapshot(path.join(cwd, 'base.json'), workspaceWith([
69	    { id: 'old', title: 'Old', body: 'body text', tags: [] },
70	  ]));
71	  writeSnapshot(path.join(cwd, 'incoming.json'), workspaceWith([
72	    { id: 'new', title: 'New', body: 'body text', tags: [] },
73	  ]));
74	
75	  const { status, stdout } = runMigrate(['base.json', 'incoming.json', 'out.json', 'replace'], cwd);
76	  assert.equal(status, 0);
77	  const snapshot = JSON.parse(stdout.trim());
78	  assert.deepEqual(snapshot.documents.map((document) => document.id), ['new']);
79	});
80	
81	test('migrate --dry-run prints the projection without touching or creating the output', () => {
82	  const cwd = tempDir();
83	  writeSnapshot(path.join(cwd, 'base.json'), workspaceWith([
