195	  // write (normalized content unchanged): the request still succeeds, but no
196	  // revision is appended and nothing is persisted.
197	  function commit(mutate) {
198	    const candidate = new Workspace();
199	    for (const document of current.list()) candidate.add(document);
200	    const nextLedger = ledger ? ledger.clone() : null;
201	    const changed = mutate(candidate, nextLedger);
202	    if (changed === false) {
203	      return current.exportJSON();
204	    }
205	    const snapshot = candidate.exportJSON();
206	    save(snapshot, nextLedger ? nextLedger.exportJSON(snapshot.checksum) : null);
207	    current = candidate;
208	    ledger = nextLedger;
209	    return snapshot;
