1	#!/usr/bin/env node
2	import fs from 'node:fs';
3	import path from 'node:path';
4	import { createDocumentServer } from './server.js';
5	import { HistoryStore, loadHistoryFile } from './history.js';
6	import { SnapshotError, Workspace, snapshotFromDocuments } from './workspace.js';
7	import { exportMarkdownPackage, importMarkdownPackage } from './markdown.js';
8	
9	function demo() {
10	  const workspace = new Workspace();
11	  workspace.add({ id: 'welcome', title: '欢迎使用', body: '从 [[architecture]] 开始了解工作台。', tags: ['入门', 'Markdown'] });
12	  workspace.add({ id: 'architecture', title: '架构备忘', body: '本地优先的文档与双向链接基线。返回 [[welcome]]。', tags: ['架构', 'markdown'] });
13	  const result = {
14	    product: 'Lattice Workbench',
15	    documents: workspace.list(),
16	    search: workspace.search('markdown').map(({ id, title }) => ({ id, title })),
17	    relationships: Object.fromEntries(workspace.list().map(({ id }) => [id, workspace.links(id)])),
18	  };
19	  process.stdout.write(`${JSON.stringify(result, null, 2)}\n`);
20	}
21	
22	function readSnapshotFile(file) {
23	  try {
24	    return fs.readFileSync(file, 'utf8');
25	  } catch (error) {
26	    throw new SnapshotError('IO_ERROR', `cannot read snapshot file ${file}: ${error.message}`);
27	  }
28	}
29	
30	function atomicWrite(file, content) {
31	  const directory = path.dirname(path.resolve(file));
32	  const temp = stagingPath(file);
33	  try {
34	    fs.writeFileSync(temp, content, 'utf8');
35	    fs.renameSync(temp, file);
36	  } catch (error) {
37	    try {
38	      fs.rmSync(temp, { force: true });
39	    } catch {
40	      // best-effort cleanup of the staging file
41	    }
42	    throw new SnapshotError('IO_ERROR', `cannot write snapshot file ${file}: ${error.message}`);
43	  }
44	}
45	
46	function stagingPath(file) {
47	  const directory = path.dirname(path.resolve(file));
48	  return path.join(directory, `.${path.basename(file)}.${process.pid}.tmp`);
49	}
50	
51	// Resolves a path to its real location, following every symlink that exists;
52	// the non-existent tail is appended verbatim. Containment checks use this so
53	// path aliases (symlinks, `..`) cannot hide that two paths actually overlap.
54	function realPathOf(target) {
55	  const resolved = path.resolve(target);
56	  const missing = [];
57	  let current = resolved;
58	  while (true) {
59	    try {
60	      return path.join(fs.realpathSync(current), ...missing.reverse());
61	    } catch {
62	      const parent = path.dirname(current);
63	      if (parent === current) return path.join(current, ...missing.reverse());
64	      missing.push(path.basename(current));
65	      current = parent;
66	    }
67	  }
68	}
69	
70	function parseMigrateArgs(args) {
71	  const positionals = [];
72	  let dryRun = false;
73	  for (const arg of args) {
74	    if (arg === '--dry-run') {
75	      dryRun = true;
76	    } else if (arg.startsWith('--')) {
77	      throw new SnapshotError('INVALID_OPTIONS', `unknown option: ${arg}`);
78	    } else {
79	      positionals.push(arg);
80	    }
81	  }
82	  if (positionals.length !== 4) {
83	    throw new SnapshotError('INVALID_OPTIONS', 'usage: migrate <base> <incoming> <output> <mode> [--dry-run]');
84	  }
85	  const [base, incoming, output, mode] = positionals;
86	  if (mode !== 'merge' && mode !== 'replace') {
87	    throw new SnapshotError('INVALID_OPTIONS', "mode must be 'merge' or 'replace'");
88	  }
89	  return { base, incoming, output, mode, dryRun };
90	}
91	
92	function migrate(args) {
93	  const { base, incoming, output, mode, dryRun } = parseMigrateArgs(args);
94	
95	  const workspace = new Workspace();
96	  workspace.importJSON(readSnapshotFile(base), { mode: 'replace' });
97	  const snapshot = workspace.importJSON(readSnapshotFile(incoming), { mode, dryRun });
98	
99	  const rendered = `${JSON.stringify(snapshot)}\n`;
100	  if (!dryRun) atomicWrite(output, rendered);
101	  process.stdout.write(rendered);
102	}
103	
104	function parseExportMdArgs(args) {
105	  const positionals = [];
106	  for (const arg of args) {
107	    if (arg.startsWith('--')) {
108	      throw new SnapshotError('INVALID_OPTIONS', `unknown option: ${arg}`);
109	    }
110	    positionals.push(arg);
111	  }
112	  if (positionals.length !== 2) {
113	    throw new SnapshotError('INVALID_OPTIONS', 'usage: export-md <snapshot> <output-dir>');
114	  }
115	  return { snapshotFile: positionals[0], outputDir: positionals[1] };
116	}
117	
118	function exportMd(args) {
119	  const { snapshotFile, outputDir } = parseExportMdArgs(args);
120	
121	  // Option checks run before any I/O. The target must not be a symlink and
122	  // must not contain the source snapshot, including through path aliases.
123	  if (fs.existsSync(outputDir)) {
124	    const stat = fs.lstatSync(outputDir);
125	    if (stat.isSymbolicLink()) {
126	      throw new SnapshotError('INVALID_OPTIONS', 'output directory must not be a symbolic link');
127	    }
128	  }
129	  const sourceReal = realPathOf(snapshotFile);
130	  const outputReal = realPathOf(outputDir);
131	  if (sourceReal === outputReal || sourceReal.startsWith(`${outputReal}${path.sep}`)) {
132	    throw new SnapshotError('INVALID_OPTIONS', 'output directory must not contain the source snapshot');
133	  }
134	
135	  const workspace = new Workspace();
136	  const snapshot = workspace.importJSON(readSnapshotFile(snapshotFile), { mode: 'replace' });
137	  const manifest = exportMarkdownPackage(snapshot, outputDir);
138	  process.stdout.write(`${JSON.stringify(manifest)}\n`);
139	}
140	
141	function parseImportMdArgs(args) {
142	  const positionals = [];
143	  let dryRun = false;
144	  for (const arg of args) {
145	    if (arg === '--dry-run') {
146	      dryRun = true;
147	    } else if (arg.startsWith('--')) {
148	      throw new SnapshotError('INVALID_OPTIONS', `unknown option: ${arg}`);
149	    } else {
150	      positionals.push(arg);
151	    }
152	  }
153	  if (positionals.length !== 4) {
154	    throw new SnapshotError('INVALID_OPTIONS', 'usage: import-md <base> <input-dir> <output> <mode> [--dry-run]');
155	  }
156	  const [base, inputDir, output, mode] = positionals;
157	  if (mode !== 'merge' && mode !== 'replace') {
158	    throw new SnapshotError('INVALID_OPTIONS', "mode must be 'merge' or 'replace'");
159	  }
160	  return { base, inputDir, output, mode, dryRun };
161	}
162	
163	function importMd(args) {
164	  const { base, inputDir, output, mode, dryRun } = parseImportMdArgs(args);
165	
166	  // The output snapshot must not live inside the package directory, including
167	  // through path aliases; the package itself is never written to.
168	  const inputReal = realPathOf(inputDir);
169	  const outputReal = realPathOf(output);
170	  if (outputReal === inputReal || outputReal.startsWith(`${inputReal}${path.sep}`)) {
171	    throw new SnapshotError('INVALID_OPTIONS', 'output snapshot must not be inside the input directory');
172	  }
173	
174	  const workspace = new Workspace();
175	  workspace.importJSON(readSnapshotFile(base), { mode: 'replace' });
176	  const incoming = importMarkdownPackage(inputDir);
177	  const snapshot = workspace.importJSON(incoming, { mode, dryRun });
178	
179	  const rendered = `${JSON.stringify(snapshot)}\n`;
180	  if (!dryRun) atomicWrite(output, rendered);
181	  process.stdout.write(rendered);
182	}
183	
184	function parsePort(value) {
185	  if (!/^\d+$/u.test(value)) {
186	    throw new SnapshotError('INVALID_OPTIONS', `invalid port: ${value}`);
187	  }
188	  const port = Number(value);
189	  if (port > 65535) {
190	    throw new SnapshotError('INVALID_OPTIONS', `invalid port: ${value}`);
191	  }
192	  return port;
193	}
194	
195	function parseServeArgs(args) {
196	  const positionals = [];
197	  let port = 3000;
198	  let historyFile = null;
199	  for (let index = 0; index < args.length; index += 1) {
200	    const arg = args[index];
201	    if (arg === '--port') {
202	      index += 1;
203	      if (index >= args.length) throw new SnapshotError('INVALID_OPTIONS', '--port requires a value');
204	      port = parsePort(args[index]);
205	    } else if (arg.startsWith('--port=')) {
206	      port = parsePort(arg.slice('--port='.length));
207	    } else if (arg === '--history') {
208	      index += 1;
209	      if (index >= args.length || args[index] === '') throw new SnapshotError('INVALID_OPTIONS', '--history requires a value');
210	      historyFile = args[index];
211	    } else if (arg.startsWith('--history=')) {
212	      historyFile = arg.slice('--history='.length);
213	      if (historyFile === '') throw new SnapshotError('INVALID_OPTIONS', '--history requires a value');
214	    } else if (arg.startsWith('--')) {
215	      throw new SnapshotError('INVALID_OPTIONS', `unknown option: ${arg}`);
216	    } else {
217	      positionals.push(arg);
218	    }
219	  }
220	  if (positionals.length !== 1) {
221	    throw new SnapshotError('INVALID_OPTIONS', 'usage: serve <snapshot> [--port <port>] [--history <file>]');
222	  }
223	  if (historyFile !== null && path.resolve(positionals[0]) === path.resolve(historyFile)) {
224	    throw new SnapshotError('INVALID_OPTIONS', 'snapshot and history must be different files');
225	  }
226	  return { file: positionals[0], port, historyFile };
227	}
228	
229	function readText(file) {
230	  return fs.readFileSync(file, 'utf8');
231	}
232	
233	function writeStaging(file, content) {
234	  const temp = stagingPath(file);
235	  try {
236	    fs.writeFileSync(temp, content, 'utf8');
237	  } catch (error) {
238	    try {
239	      fs.rmSync(temp, { force: true });
240	    } catch {
241	      // best-effort cleanup
242	    }
243	    throw new SnapshotError('IO_ERROR', `cannot write file ${file}: ${error.message}`);
244	  }
245	  return temp;
246	}
247	
248	function removeQuiet(file) {
249	  try {
250	    fs.rmSync(file, { force: true });
251	  } catch {
252	    // best-effort cleanup
253	  }
254	}
255	
256	// Commits snapshot and history together. The history file is the commit
257	// marker: it is installed first and embeds the new snapshot checksum, so a
258	// kill between the two renames leaves a history the next startup replays to
259	// reconstruct the snapshot. A failed I/O step rolls the files back to the
260	// pre-commit state; the caller only swaps in-memory state after this returns.
261	function commitWithHistory(snapshotFile, historyFile, backupFile, snapshot, historySnapshot) {
262	  const snapshotText = `${JSON.stringify(snapshot)}\n`;
263	  const historyText = `${JSON.stringify(historySnapshot)}\n`;
264	  const snapshotTemp = writeStaging(snapshotFile, snapshotText);
265	  let historyTemp;
266	  try {
267	    historyTemp = writeStaging(historyFile, historyText);
268	  } catch (error) {
269	    removeQuiet(snapshotTemp);
270	    throw error;
271	  }
272	  const hadHistory = fs.existsSync(historyFile);
273	  try {
274	    if (hadHistory) fs.renameSync(historyFile, backupFile);
275	    fs.renameSync(historyTemp, historyFile);
276	  } catch (error) {
277	    if (hadHistory) {
278	      try {
279	        fs.renameSync(backupFile, historyFile);
280	      } catch {
281	        // startup recovery reconciles whatever remains
282	      }
283	    }
284	    removeQuiet(snapshotTemp);
285	    removeQuiet(historyTemp);
286	    throw new SnapshotError('IO_ERROR', `cannot write history file ${historyFile}: ${error.message}`);
287	  }
288	  try {
289	    fs.renameSync(snapshotTemp, snapshotFile);
290	  } catch (error) {
291	    try {
292	      if (hadHistory) {
293	        fs.renameSync(backupFile, historyFile);
294	      } else {
295	        fs.rmSync(historyFile, { force: true });
296	      }
297	    } catch {
298	      // startup recovery reconciles whatever remains
299	    }
300	    removeQuiet(historyTemp);
301	    throw new SnapshotError('IO_ERROR', `cannot write snapshot file ${snapshotFile}: ${error.message}`);
302	  }
303	  removeQuiet(backupFile);
304	}
305	
306	// Loads the snapshot/history pair and brings both to a single consistent
307	// state. Returns { workspace, ledger }. Throws a SnapshotError (IO_ERROR,
308	// INVALID_SNAPSHOT, or INVALID_HISTORY) on any unrecoverable problem; files
309	// are left untouched in that case.
310	function loadState(file, historyFile) {
311	  const workspace = new Workspace();
312	  let snapshot = null;
313	  if (fs.existsSync(file)) {
314	    const text = readSnapshotFile(file);
315	    workspace.importJSON(text, { mode: 'replace' });
316	    snapshot = workspace.exportJSON();
317	  } else {
318	    snapshot = workspace.exportJSON();
319	  }
320	
321	  if (historyFile === null) return { workspace, ledger: null };
322	
323	  const backupFile = `${historyFile}.bak`;
324	  // A kill between moving the old history aside and installing the new one
325	  // leaves only the backup; restore the pre-commit history before proceeding.
326	  if (!fs.existsSync(historyFile) && fs.existsSync(backupFile)) {
327	    try {
328	      fs.renameSync(backupFile, historyFile);
329	    } catch (error) {
330	      throw new SnapshotError('IO_ERROR', `cannot recover history file ${historyFile}: ${error.message}`);
331	    }
332	  }
333	
334	  if (!fs.existsSync(historyFile)) {
335	    // First run with a history file: revision 1 baselines the current content.
336	    // The file itself appears with the first successful write.
337	    return { workspace, ledger: HistoryStore.baseline(workspace.list()) };
338	  }
339	
340	  const ledger = loadHistoryFile(historyFile, readText);
341	  removeQuiet(backupFile);
342	  if (ledger.snapshotChecksum === snapshot.checksum) {
343	    return { workspace, ledger };
344	  }
345	
346	  // The files disagree: the history ledger is authoritative (it records every
347	  // acknowledged commit). Reconstruct the snapshot from its replay and install
348	  // it atomically.
349	  const recovered = snapshotFromDocuments(ledger.replayedDocuments().values());
350	  if (recovered.checksum !== ledger.snapshotChecksum) {
351	    throw new SnapshotError('INVALID_HISTORY', 'history cannot be reconciled to a consistent snapshot');
352	  }
353	  const recoveredWorkspace = new Workspace();
354	  recoveredWorkspace.importJSON(recovered, { mode: 'replace' });
355	  atomicWrite(file, `${JSON.stringify(recovered)}\n`);
356	  return { workspace: recoveredWorkspace, ledger };
357	}
358	
359	function serve(args) {
360	  const { file, port, historyFile } = parseServeArgs(args);
361	  const { workspace, ledger } = loadState(file, historyFile);
362	
363	  const backupFile = historyFile === null ? null : `${historyFile}.bak`;
364	  const server = createDocumentServer({
365	    workspace,
366	    history: ledger,
367	    save: (snapshot, historySnapshot) => {
368	      if (historyFile === null) {
369	        atomicWrite(file, `${JSON.stringify(snapshot)}\n`);
370	      } else {
371	        commitWithHistory(file, historyFile, backupFile, snapshot, historySnapshot);
372	      }
373	    },
374	  });
375	  server.on('error', (error) => {
376	    reportError(new SnapshotError('IO_ERROR', `cannot serve ${file}: ${error.message}`));
377	  });
378	  server.listen(port, '127.0.0.1', () => {
379	    const address = server.address();
380	    process.stdout.write(`${JSON.stringify({ host: address.address, port: address.port })}\n`);
381	  });
382	}
383	
384	function reportError(error) {
385	  const payload = { code: error instanceof SnapshotError ? error.code : 'IO_ERROR' };
386	  if (typeof error.message === 'string') payload.message = error.message;
387	  if (Array.isArray(error.ids)) payload.ids = error.ids;
388	  process.stderr.write(`${JSON.stringify(payload)}\n`);
389	  process.exitCode = 1;
390	}
391	
392	const command = process.argv[2];
393	if (command === 'demo') {
394	  demo();
395	} else if (command === 'migrate') {
396	  try {
397	    migrate(process.argv.slice(3));
398	  } catch (error) {
399	    reportError(error);
400	  }
401	} else if (command === 'export-md') {
402	  try {
403	    exportMd(process.argv.slice(3));
404	  } catch (error) {
405	    reportError(error);
406	  }
407	} else if (command === 'import-md') {
408	  try {
409	    importMd(process.argv.slice(3));
410	  } catch (error) {
411	    reportError(error);
412	  }
413	} else if (command === 'serve') {
414	  try {
415	    serve(process.argv.slice(3));
416	  } catch (error) {
417	    reportError(error);
418	  }
419	} else {
420	  process.stderr.write('Usage: node src/cli.js demo | node src/cli.js migrate <base> <incoming> <output> <mode> [--dry-run] | node src/cli.js export-md <snapshot> <output-dir> | node src/cli.js import-md <base> <input-dir> <output> <mode> [--dry-run] | node src/cli.js serve <snapshot> [--port <port>] [--history <file>]\n');
421	  process.exitCode = 1;
422	}
